import React from 'react';

export function CommentView({ comment }) {
  return (
    <div className="comment">
      <h3>User said:</h3>
      {/* dangerouslySetInnerHTML 대신 텍스트 노드로 렌더링하여 XSS 공격을 방지 */}
      <div>{comment}</div>
    </div>
  );
}
```

한줄 요약: `dangerouslySetInnerHTML`을 제거하고 React의 기본 텍스트 렌더링(`{comment}`)을 사용하면, React가 자동으로 HTML 특수문자를 이스케이프 처리하여 Stored XSS 취약점을 차단할 수 있습니다.
